class Solution {
public:
    int robotSim(vector<int>& commands, vector<vector<int>>& obstacles) {
        set<pair<int, int>> obs;
        for (auto& o : obstacles) obs.insert({o[0], o[1]});
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int d = 0, x = 0, y = 0, max_dist = 0;
        for (int cmd : commands) {
            if (cmd == -1) {
                d = (d + 1) % 4;
            } else if (cmd == -2) {
                d = (d + 3) % 4;
            } else {
                int dx = dirs[d][0], dy = dirs[d][1];
                for (int i = 0; i < cmd; i++) {
                    if (obs.count({x + dx, y + dy})) break;
                    x += dx;
                    y += dy;
                    max_dist = max(max_dist, x * x + y * y);
                }
            }
        }
        return max_dist;
    }
};

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Set<String> obs = new HashSet<>();
        for (int[] o : obstacles) obs.add(o[0] + "," + o[1]);
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int d = 0, x = 0, y = 0, maxDist = 0;
        for (int cmd : commands) {
            if (cmd == -1) {
                d = (d + 1) % 4;
            } else if (cmd == -2) {
                d = (d + 3) % 4;
            } else {
                int dx = dirs[d][0], dy = dirs[d][1];
                for (int i = 0; i < cmd; i++) {
                    if (obs.contains((x + dx) + "," + (y + dy))) break;
                    x += dx;
                    y += dy;
                    maxDist = Math.max(maxDist, x * x + y * y);
                }
            }
        }
        return maxDist;
    }
}

var robotSim = function(commands, obstacles) {
    const obs = new Set(obstacles.map(o => `${o[0]},${o[1]}`));
    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let d = 0, x = 0, y = 0, maxDist = 0;
    for (const cmd of commands) {
        if (cmd === -1) {
            d = (d + 1) % 4;
        } else if (cmd === -2) {
            d = (d + 3) % 4;
        } else {
            const [dx, dy] = dirs[d];
            for (let i = 0; i < cmd; i++) {
                if (obs.has(`${x + dx},${y + dy}`)) break;
                x += dx;
                y += dy;
                maxDist = Math.max(maxDist, x * x + y * y);
            }
        }
    }
    return maxDist;
};
